<?php
namespace App\Http\Controllers;
use App\Models\{Report,ServiceRequest};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class ReportController extends Controller {
 public function index(Request $r){$this->requireCondition(in_array($r->user()->role,['admin','assistant','sfu_head']),403);return view('staff.reports',['reports'=>Report::with('user')->latest()->get()]);}
 public function store(Request $r){$this->requireCondition($r->user()->role==='sfu_head',403);$v=$r->validate(['title'=>'required|string|max:150','academic_year'=>'required|string|max:30','semester'=>'required|in:1st Semester,2nd Semester,Summer','summary'=>'required|string|min:30|max:5000']);
  $snapshot=ServiceRequest::where('kind','scholarship')->where('status','approved')->get()->filter(fn($q)=>($q->details['academic_year']??null)===$v['academic_year']&&($q->details['semester']??null)===$v['semester'])->map(fn($q)=>['ticket'=>$q->ticket,'name'=>$q->user->name,'student_id'=>$q->user->student_id,'rate'=>$q->details['discount_rate']??0])->values()->all();
  Report::create([...$v,'user_id'=>$r->user()->id,'snapshot'=>$snapshot]);return back()->with('success','Semester report submitted to the assistant for forwarding to admin.');
 }
 public function review(Request $r,Report $report){$this->requireCondition(in_array($r->user()->role,['admin','assistant']),403);$v=$r->validate(['status'=>'required|in:awaiting_admin,needs_revision,approved,rejected','review_note'=>'required|string|min:5|max:3000']);DB::transaction(function()use($r,$report,$v){$q=Report::lockForUpdate()->findOrFail($report->id);$allowed=$r->user()->role==='assistant'&&$q->status==='pending'?['awaiting_admin','needs_revision']:($r->user()->role==='admin'&&$q->status==='awaiting_admin'?['approved','rejected','needs_revision']:[]);$this->requireCondition(in_array($v['status'],$allowed),422,'Report must be forwarded by the assistant before final admin review.');$q->update([...$v,'reviewed_by'=>$r->user()->id]);DB::table('audit_logs')->insert(['user_id'=>$r->user()->id,'action'=>'report.'.$v['status'],'subject'=>$q->title,'details'=>$v['review_note'],'created_at'=>now()]);});return back()->with('success','Report decision saved.');}
 public function revise(Request $r,Report $report){$this->requireCondition($r->user()->role==='sfu_head'&&$report->user_id===$r->user()->id,403);$v=$r->validate(['summary'=>'required|string|min:30|max:5000']);DB::transaction(function()use($r,$report,$v){$q=Report::lockForUpdate()->findOrFail($report->id);$this->requireCondition($q->status==='needs_revision',422);$q->update(['summary'=>$v['summary'],'status'=>'pending']);DB::table('audit_logs')->insert(['user_id'=>$r->user()->id,'action'=>'report.resubmitted','subject'=>$q->title,'details'=>'Summary revised; original award snapshot preserved.','created_at'=>now()]);});return back()->with('success','Report resubmitted to the assistant.');}
 public function settings(Request $r){$this->requireCondition($r->user()->role==='admin',403);$v=$r->validate(['tuition'=>'required|numeric|between:0,1000000','laboratory'=>'required|numeric|between:0,1000000','miscellaneous'=>'required|numeric|between:0,1000000','academic_year'=>'required|string|max:30','semester'=>'required|in:1st Semester,2nd Semester,Summer']);DB::transaction(function()use($r,$v){foreach($v as $key=>$value)DB::table('settings')->updateOrInsert(['key'=>$key],['value'=>in_array($key,['tuition','laboratory','miscellaneous'])?(string)(int)round($value*100):$value]);DB::table('audit_logs')->insert(['user_id'=>$r->user()->id,'action'=>'settings.update','subject'=>'Fee schedule and term','details'=>json_encode($v),'created_at'=>now()]);});return back()->with('success','Fee schedule and term updated.');}
}

